  // ═══════════════════════════════════════════
  // Module-scoped audio processing functions
  // ═══════════════════════════════════════════

  // Search bounds for a sung fundamental. Restricting the lag range is most of
  // the speed win: the old detector correlated every lag across the whole
  // 4096-sample buffer (~8.4M multiply-adds) once per animation frame.
  var PITCH_MIN_HZ = 55;   // ~A1, below any sung fundamental
  var PITCH_MAX_HZ = 1600; // ~G6, above soprano high C
  var CLARITY_MIN = 0.55;  // below this the frame is breath/consonant, not a pitch
  var PITCH_DECIMATION = 4;

  /**
   * Normalized square difference (McLeod pitch method) over [minLag, maxLag].
   *
   * Picks the FIRST key maximum within 90% of the global best rather than the
   * global best itself. That choice is what stops a rich voice from locking onto
   * its own subharmonic and reading an octave low — the old detector took the
   * global max and had no defence against it.
   *
   * Returns { lag, clarity } with lag parabolically interpolated, or lag -1.
   */
  function findBestLag(sig, minLag, maxLag) {
    var n = sig.length;
    var win = Math.floor(n / 2);
    if (minLag < 1) minLag = 1;
    if (maxLag > win - 2) maxLag = win - 2;
    if (maxLag <= minLag) return { lag: -1, clarity: 0 };

    var nsdf = new Float32Array(maxLag + 2);
    for (var lag = minLag; lag <= maxLag; lag++) {
      var corr = 0, energy = 0;
      for (var j = 0; j < win; j++) {
        var a = sig[j], b = sig[j + lag];
        corr += a * b;
        energy += a * a + b * b;
      }
      nsdf[lag] = energy > 0 ? (2 * corr) / energy : 0;
    }

    var peak = 0;
    for (var p = minLag; p <= maxLag; p++) { if (nsdf[p] > peak) peak = nsdf[p]; }
    if (peak <= 0) return { lag: -1, clarity: 0 };

    var threshold = peak * 0.9;
    var chosen = -1;
    for (var q = minLag + 1; q < maxLag; q++) {
      if (nsdf[q] > threshold && nsdf[q] >= nsdf[q - 1] && nsdf[q] >= nsdf[q + 1]) { chosen = q; break; }
    }
    if (chosen < 0) return { lag: -1, clarity: 0 };

    // Parabolic interpolation around the peak for sub-sample period resolution.
    var y1 = nsdf[chosen - 1], y2 = nsdf[chosen], y3 = nsdf[chosen + 1];
    var denom = 2 * (2 * y2 - y1 - y3);
    var lagOut = denom !== 0 ? chosen + (y3 - y1) / denom : chosen;
    if (!isFinite(lagOut) || lagOut <= 0) return { lag: -1, clarity: 0 };
    return { lag: lagOut, clarity: Math.min(1, Math.max(0, y2)) };
  }

  /**
   * Pitch detection: coarse pass on a 4x-decimated copy, then refine at full
   * rate around that estimate. ~0.5M multiply-adds instead of ~8.4M.
   *
   * Returns { freq, clarity }; freq is -1 when no pitch is present. Callers
   * should reject low-clarity frames rather than trusting every reading —
   * a bad frame written into rangeLow/rangeHigh corrupts a stored vocal range.
   */
  function detectPitch(buf, sampleRate) {
    if (calculateRMS(buf) < 0.01) return { freq: -1, clarity: 0 };

    var dsRate = sampleRate / PITCH_DECIMATION;
    var dsLen = Math.floor(buf.length / PITCH_DECIMATION);
    var ds = new Float32Array(dsLen);
    for (var i = 0; i < dsLen; i++) {
      var acc = 0;
      for (var k = 0; k < PITCH_DECIMATION; k++) acc += buf[i * PITCH_DECIMATION + k];
      ds[i] = acc / PITCH_DECIMATION;
    }

    var coarse = findBestLag(ds, Math.floor(dsRate / PITCH_MAX_HZ), Math.ceil(dsRate / PITCH_MIN_HZ));
    if (coarse.lag <= 0) return { freq: -1, clarity: 0 };

    var centre = Math.round(coarse.lag * PITCH_DECIMATION);
    var span = PITCH_DECIMATION * 2;
    var fine = findBestLag(buf, centre - span, centre + span);
    if (fine.lag <= 0 || fine.clarity < CLARITY_MIN) return { freq: -1, clarity: 0 };

    var freq = sampleRate / fine.lag;
    if (!isFinite(freq) || freq < PITCH_MIN_HZ || freq > PITCH_MAX_HZ) return { freq: -1, clarity: 0 };
    return { freq: freq, clarity: fine.clarity };
  }

  /** Legacy shim for callers that only want the frequency (or -1). */
  function autoCorrelate(buf, sampleRate) {
    return detectPitch(buf, sampleRate).freq;
  }

  // ── Rate-independent "held the note" accumulator ──
  // Thresholds in milliseconds, not update counts. See HOLD_* constants below.
  var HOLD_MATCH_MS = 1000;     // pitch match: hold the target for a second
  var HOLD_RANGE_MS = 1000;     // vocal range: steady for a second before capturing
  var HOLD_SIGHTREAD_MS = 1000; // sight reading: settle on each note
  var HOLD_INTERVAL_MS = 800;   // interval singing, per the original intent
  var HOLD_MAX_STEP_MS = 250;   // a backgrounded tab must not credit a whole second

  /**
   * Accrue (or bleed off) held time on a hold ref.
   *
   * ref.current is { ms, last }. multiplier is 1 while the target is held, or
   * negative to give progress back when it is lost — which preserves the original
   * forgiveness behaviour (a brief wobble cost you progress instead of resetting).
   * Returns the accumulated milliseconds.
   */
  function accrueHold(ref, nowMs, multiplier) {
    var st = ref.current;
    if (!st || typeof st !== 'object') { st = { ms: 0, last: nowMs }; ref.current = st; }
    var dt = nowMs - st.last;
    st.last = nowMs;
    if (!(dt > 0) || dt > HOLD_MAX_STEP_MS) dt = 0;
    st.ms += dt * multiplier;
    if (st.ms < 0) st.ms = 0;
    return st.ms;
  }

  /** Clear a hold ref without crediting the gap since its last update. */
  function resetHold(ref) { ref.current = { ms: 0, last: Date.now() }; }

  /** RMS volume calculation */
  function calculateRMS(buf) {
    var sum = 0;
    for (var i = 0; i < buf.length; i++) sum += buf[i] * buf[i];
    return Math.sqrt(sum / buf.length);
  }

  // ═══════════════════════════════════════════
  // Music theory functions
  // ═══════════════════════════════════════════

  var NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

  /**
   * Convert frequency to note information.
   * Returns { note, octave, cents, midi, freq }
   */
  function frequencyToNote(freq) {
    if (freq <= 0) return { note: '--', octave: 0, cents: 0, midi: 0, freq: 0 };
    var midi = 69 + 12 * Math.log2(freq / 440);
    var midiRounded = Math.round(midi);
    var cents = Math.round((midi - midiRounded) * 100);
    var noteIdx = ((midiRounded % 12) + 12) % 12;
    var octave = Math.floor(midiRounded / 12) - 1;
    return {
      note: NOTE_NAMES[noteIdx],
      octave: octave,
      cents: cents,
      midi: midiRounded,
      freq: freq
    };
  }

  /** Convert MIDI note number to frequency */
  function midiToFreq(midi) {
    return 440 * Math.pow(2, (midi - 69) / 12);
  }

  /** Convert MIDI note number to note name */
  function midiToNoteName(midi) {
    var noteIdx = ((midi % 12) + 12) % 12;
    var octave = Math.floor(midi / 12) - 1;
    return {
      note: NOTE_NAMES[noteIdx],
      octave: octave,
      str: NOTE_NAMES[noteIdx] + octave
    };
  }

  // ═══════════════════════════════════════════
  // Vibrato analysis — ported from Rachel's biofeedback tools
  // ═══════════════════════════════════════════

  // Vibrato extent is conventionally the peak-to-peak pitch excursion. Estimating it
  // from RMS rather than from observed max-minus-min keeps one bad frame from
  // dominating (squaring still pulls the estimate up, but roughly half as far), so
  // scale RMS to the peak-to-peak of the equivalent sine: pp = 2*sqrt(2)*RMS.
  var VIBRATO_RMS_TO_EXTENT = 2 * Math.SQRT2;
  // Zero-crossing rate stays accurate down to about 18 samples/sec for vibrato up to
  // 8 Hz; below that it collapses (a real 6 Hz read as 1.0 Hz at 12 samples/sec), so
  // a sparser window must not be turned into a diagnosis.
  var VIBRATO_MIN_SAMPLE_HZ = 18;

  function analyzeVibrato(history) {
    var none = { rate: 0, depth: 0, extentCents: 0, sampleHz: 0, reliable: false };
    if (!history || history.length < 10) return none;
    var midiValues = history.map(function(h) { return h.midi; });
    var mean = midiValues.reduce(function(a, b) { return a + b; }, 0) / midiValues.length;
    var deviations = midiValues.map(function(m) { return (m - mean) * 100; });
    var variance = deviations.reduce(function(sum, d) { return sum + d * d; }, 0) / deviations.length;
    var rms = Math.sqrt(variance);
    var crossings = 0;
    for (var i = 1; i < deviations.length; i++) {
      if ((deviations[i] >= 0 && deviations[i - 1] < 0) || (deviations[i] < 0 && deviations[i - 1] >= 0)) crossings++;
    }
    var durationSec = (history[history.length - 1].time - history[0].time) / 1000;
    if (!(durationSec > 0)) return none;
    var rate = (crossings / 2) / durationSec;
    var sampleHz = (history.length - 1) / durationSec;
    return {
      rate: rate,
      depth: rms * 2,                              // legacy index, kept for callers
      extentCents: rms * VIBRATO_RMS_TO_EXTENT,    // peak-to-peak, the displayed unit
      sampleHz: sampleHz,
      reliable: sampleHz >= VIBRATO_MIN_SAMPLE_HZ
    };
  }

  // Thresholds in true peak-to-peak cents. These are the original 10/30/80/100
  // "depth" boundaries carried across by the same factor, so precisely the same
  // singing passes each band — only the unit is now the one the UI claims.
  // The boundaries themselves still want a vocal-pedagogy review; see
  // MUSIC_TOOLS_REVIEW.md.
  var VIB_STRAIGHT_MAX = 10 * VIBRATO_RMS_TO_EXTENT / 2;   // 14 cents
  var VIB_HEALTHY_MIN = 30 * VIBRATO_RMS_TO_EXTENT / 2;    // 42 cents
  var VIB_HEALTHY_MAX = 80 * VIBRATO_RMS_TO_EXTENT / 2;    // 113 cents
  var VIB_WIDE_MAX = 100 * VIBRATO_RMS_TO_EXTENT / 2;      // 141 cents
  var VIB_DEVELOPING_MIN = 15 * VIBRATO_RMS_TO_EXTENT / 2; // 21 cents

  // ═══════════════════════════════════════════
  // Reference tone synthesis (shared AudioContext)
  // ═══════════════════════════════════════════

  var _sharedAudioCtx = null;
  var _activeOscillator = null;
  var _activeGain = null;

  function getSharedAudioCtx() {
    if (!_sharedAudioCtx || _sharedAudioCtx.state === 'closed') {
      _sharedAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (_sharedAudioCtx.state === 'suspended') {
      _sharedAudioCtx.resume();
    }
    return _sharedAudioCtx;
  }

  function stopRefTone() {
    if (_activeOscillator) {
      try { _activeOscillator.stop(); } catch(e) { /* ignore */ }
      _activeOscillator = null;
    }
    if (_activeGain) {
      try { _activeGain.disconnect(); } catch(e) { /* ignore */ }
      _activeGain = null;
    }
  }

  /**
   * Play a reference tone at given frequency.
   * duration: seconds (0 = indefinite until stopped)
   * volume: 0-1 (default 0.12)
   */
  function playRefTone(freq, duration, volume) {
    stopRefTone();
    var ctx = getSharedAudioCtx();
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    gain.gain.setValueAtTime(volume || 0.12, ctx.currentTime);
    // Soft attack to avoid click
    gain.gain.setValueAtTime(0, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(volume || 0.12, ctx.currentTime + 0.05);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    _activeOscillator = osc;
    _activeGain = gain;
    if (duration && duration > 0) {
      // Soft release
      gain.gain.setValueAtTime(volume || 0.12, ctx.currentTime + duration - 0.05);
      gain.gain.linearRampToValueAtTime(0, ctx.currentTime + duration);
      osc.stop(ctx.currentTime + duration);
      setTimeout(function() {
        if (_activeOscillator === osc) {
          _activeOscillator = null;
          _activeGain = null;
        }
      }, duration * 1000 + 100);
    }
    return osc;
  }

  /** Convenience: play a MIDI note */
  function playMidiNote(midi, duration, volume) {
    return playRefTone(midiToFreq(midi), duration, volume);
  }

  /**
   * Play a sequence of MIDI notes (for warm-up exercises).
   * notes: array of { midi, duration } objects
   * Returns a promise that resolves when done.
   */
  function playNoteSequence(notes, volume) {
    return new Promise(function(resolve) {
      var idx = 0;
      function playNext() {
        if (idx >= notes.length) {
          stopRefTone();
          resolve();
          return;
        }
        var n = notes[idx];
        idx++;
        playRefTone(midiToFreq(n.midi), n.duration, volume || 0.12);
        setTimeout(playNext, n.duration * 1000);
      }
      playNext();
    });
  }

  // ═══════════════════════════════════════════
  // Staff notation drawing — ported from Rachel's tools-advanced.js
  // ═══════════════════════════════════════════

  /**
   * Draw a treble clef staff.
   * opts: { x, y, width, lineGap }
   */
  function drawStaff(canvas, opts) {
    if (!canvas) return;
    var c = canvas.getContext('2d');
    var x = opts.x || 20;
    var y = opts.y || 40;
    var w = opts.width || (canvas.width - 40);
    var lineGap = opts.lineGap || 10;
    var isDark = opts.isDark;

    c.strokeStyle = isDark ? '#94a3b8' : '#475569';
    c.lineWidth = 1;

    // 5 staff lines
    for (var i = 0; i < 5; i++) {
      var ly = y + i * lineGap;
      c.beginPath();
      c.moveTo(x, ly);
      c.lineTo(x + w, ly);
      c.stroke();
    }

    // Treble clef symbol (simplified)
    c.font = (lineGap * 5.5) + 'px serif';
    c.fillStyle = isDark ? '#94a3b8' : '#475569';
    c.textAlign = 'left';
    c.fillText('\u{1D11E}', x + 2, y + lineGap * 4);

    return { staffTop: y, staffBottom: y + lineGap * 4 };
  }

  /**
   * Convert note name + octave to staff Y position.
   * Treble clef: bottom line = E4, top line = F5.
   * Returns Y coordinate.
   */
  function noteToStaffY(noteName, octave, staffTop, lineGap) {
    // Position mapping: each note gets a half-lineGap
    // F5 = staffTop (line 1)
    // E5 = staffTop + lineGap * 0.5
    // D5 = staffTop + lineGap * 1
    // C5 = staffTop + lineGap * 1.5
    // B4 = staffTop + lineGap * 2
    // A4 = staffTop + lineGap * 2.5
    // G4 = staffTop + lineGap * 3
    // F4 = staffTop + lineGap * 3.5
    // E4 = staffTop + lineGap * 4 (bottom line)
    // D4 = staffTop + lineGap * 4.5 (below staff)
    // C4 = staffTop + lineGap * 5 (middle C, one ledger line below)

    // Map note to diatonic position (C=0, D=1, E=2, F=3, G=4, A=5, B=6)
    var diatonicMap = { 'C': 0, 'C#': 0, 'D': 1, 'D#': 1, 'E': 2, 'F': 3, 'F#': 3, 'G': 4, 'G#': 4, 'A': 5, 'A#': 5, 'B': 6 };
    var diatonic = diatonicMap[noteName] !== undefined ? diatonicMap[noteName] : 0;

    // F5 reference: octave 5, diatonic 3 => position 0
    var refOctave = 5;
    var refDiatonic = 3; // F
    var refY = staffTop;
    var halfStep = lineGap / 2;

    var stepsFromRef = (octave - refOctave) * 7 + (diatonic - refDiatonic);
    return refY - stepsFromRef * halfStep;
  }

  /**
   * Draw a note on the staff.
   */
  function drawNoteOnStaff(ctx2d, x, noteName, octave, staffTop, lineGap, color) {
    var y = noteToStaffY(noteName, octave, staffTop, lineGap);
    var r = lineGap * 0.42;
    var halfStep = lineGap / 2;

    // Draw ledger lines if needed
    ctx2d.strokeStyle = color || '#1e293b';
    ctx2d.lineWidth = 1;
    var staffBottom = staffTop + lineGap * 4;

    // Ledger lines above staff
    if (y < staffTop - halfStep) {
      for (var ly = staffTop - lineGap; ly >= y - halfStep; ly -= lineGap) {
        ctx2d.beginPath();
        ctx2d.moveTo(x - r * 1.8, ly);
        ctx2d.lineTo(x + r * 1.8, ly);
        ctx2d.stroke();
      }
    }

    // Ledger lines below staff
    if (y > staffBottom + halfStep) {
      for (var ly = staffBottom + lineGap; ly <= y + halfStep; ly += lineGap) {
        ctx2d.beginPath();
        ctx2d.moveTo(x - r * 1.8, ly);
        ctx2d.lineTo(x + r * 1.8, ly);
        ctx2d.stroke();
      }
    }

    // Note head (filled ellipse) — glows in its note colour so active/coloured notes pop
    ctx2d.save();
    if (color) { ctx2d.shadowColor = color; ctx2d.shadowBlur = 8; }
    ctx2d.fillStyle = color || '#1e293b';
    ctx2d.beginPath();
    ctx2d.ellipse(x, y, r * 1.2, r, -0.3, 0, 2 * Math.PI);
    ctx2d.fill();
    ctx2d.restore();

    // Stem
    var stemDir = y > staffTop + lineGap * 2 ? -1 : 1; // up if below middle, down if above
    var stemLen = lineGap * 3.5;
    ctx2d.beginPath();
    ctx2d.moveTo(x + (stemDir === -1 ? r * 1.1 : -r * 1.1), y);
    ctx2d.lineTo(x + (stemDir === -1 ? r * 1.1 : -r * 1.1), y + stemDir * stemLen);
    ctx2d.strokeStyle = color || '#1e293b';
    ctx2d.lineWidth = 1.5;
    ctx2d.stroke();

    // Sharp symbol if needed
    if (noteName.indexOf('#') !== -1) {
      ctx2d.font = (lineGap * 1.4) + 'px sans-serif';
      ctx2d.fillStyle = color || '#1e293b';
      ctx2d.textAlign = 'right';
      ctx2d.fillText('#', x - r * 1.6, y + lineGap * 0.35);
    }
  }

  // ═══════════════════════════════════════════
  // Canvas visualization functions
  // ═══════════════════════════════════════════

  /**
   * Draw the piano roll — pitch over time mapped to musical notes.
   */
  function drawPitchRoll(canvas, history, opts) {
    if (!canvas) return;
    var c = canvas.getContext('2d');
    var W = canvas.width;
    var H = canvas.height;
    var isDark = opts && opts.isDark;
    var minMidi = (opts && opts.minMidi) || 36; // C2
    var maxMidi = (opts && opts.maxMidi) || 84; // C6

    c.clearRect(0, 0, W, H);
    c.fillStyle = isDark ? '#0f172a' : '#f1f5f9';
    c.fillRect(0, 0, W, H);

    var labelW = 32;
    var plotX = labelW;
    var plotW = W - labelW;
    var plotH = H;
    var midiRange = maxMidi - minMidi;

    // Horizontal gridlines at each note with labels
    c.font = '8px monospace';
    c.textAlign = 'right';
    for (var m = minMidi; m <= maxMidi; m++) {
      var noteInfo = midiToNoteName(m);
      var noteY = plotH - ((m - minMidi) / midiRange) * plotH;

      // Only draw C and E and G and A lines for readability
      var isC = noteInfo.note === 'C';
      var isNatural = noteInfo.note.indexOf('#') === -1;

      if (isC) {
        c.strokeStyle = isDark ? '#334155' : '#cbd5e1';
        c.lineWidth = 1;
        c.beginPath();
        c.moveTo(plotX, noteY);
        c.lineTo(W, noteY);
        c.stroke();
        c.fillStyle = isDark ? '#94a3b8' : '#475569';
        c.fillText(noteInfo.str, labelW - 3, noteY + 3);
      } else if (isNatural) {
        c.strokeStyle = isDark ? '#1e293b' : '#e2e8f0';
        c.lineWidth = 0.5;
        c.beginPath();
        c.moveTo(plotX, noteY);
        c.lineTo(W, noteY);
        c.stroke();
      }
    }

    // Draw pitch history line
    if (!history || history.length < 2) {
      c.fillStyle = isDark ? '#94a3b8' : '#475569';
      c.textAlign = 'center';
      c.font = '13px sans-serif';
      c.fillText((opts && opts.emptyLabel) || 'Start singing to see your pitch', W / 2, H / 2);
      return;
    }

    // Glow effect
    c.shadowColor = '#f43f5e';
    c.shadowBlur = 6;

    c.beginPath();
    c.lineWidth = 2.5;
    c.strokeStyle = '#f43f5e';
    var started = false;
    for (var i = 0; i < history.length; i++) {
      var entry = history[i];
      if (!entry || entry.midi <= 0) { started = false; continue; }
      var px = plotX + (i / (history.length - 1)) * plotW;
      var py = plotH - ((entry.midi - minMidi) / midiRange) * plotH;
      if (py < 0 || py > H) { started = false; continue; }
      if (!started) {
        c.stroke();
        c.beginPath();
        var centsAbs = Math.abs(entry.cents || 0);
        c.strokeStyle = centsAbs <= 10 ? '#22c55e' : centsAbs <= 25 ? '#eab308' : '#ef4444';
        c.moveTo(px, py);
        started = true;
      } else {
        var centsAbs = Math.abs(entry.cents || 0);
        c.strokeStyle = centsAbs <= 10 ? '#22c55e' : centsAbs <= 25 ? '#eab308' : '#ef4444';
        c.lineTo(px, py);
      }
    }
    c.stroke();
    c.shadowBlur = 0;

    // Current pitch dot
    var last = history[history.length - 1];
    if (last && last.midi > 0) {
      var dotY = plotH - ((last.midi - minMidi) / midiRange) * plotH;
      var cAbs = Math.abs(last.cents || 0);
      var dotColor = cAbs <= 10 ? '#22c55e' : cAbs <= 25 ? '#eab308' : '#ef4444';
      c.beginPath();
      c.arc(W - 8, dotY, 5, 0, 2 * Math.PI);
      c.fillStyle = dotColor;
      c.fill();

      // Note label near dot
      c.font = 'bold 11px sans-serif';
      c.fillStyle = isDark ? '#e2e8f0' : '#1e293b';
      c.textAlign = 'right';
      c.fillText(last.noteStr || '', W - 18, dotY - 8);
    }
  }

  /**
   * Draw cents meter — horizontal needle gauge from -50 to +50.
   */
  function drawCentsMeter(canvas, cents, isDark, labels) {
    var L = labels || {};
    if (!canvas) return;
    var c = canvas.getContext('2d');
    var W = canvas.width;
    var H = canvas.height;
    c.clearRect(0, 0, W, H);

    c.fillStyle = isDark ? '#1e293b' : '#f8fafc';
    c.fillRect(0, 0, W, H);

    var barY = 14;
    var barH = 14;
    var barX = 30;
    var barW = W - 60;
    var center = barX + barW / 2;

    // Background track
    c.fillStyle = isDark ? '#334155' : '#e2e8f0';
    c.fillRect(barX, barY, barW, barH);

    // Green zone in center (±10 cents)
    var greenW = (10 / 50) * (barW / 2);
    c.fillStyle = isDark ? 'rgba(34, 197, 94, 0.25)' : 'rgba(34, 197, 94, 0.2)';
    c.fillRect(center - greenW, barY, greenW * 2, barH);

    // Yellow zone (±10 to ±25)
    var yellowW = (25 / 50) * (barW / 2);
    c.fillStyle = isDark ? 'rgba(234, 179, 8, 0.15)' : 'rgba(234, 179, 8, 0.12)';
    c.fillRect(center - yellowW, barY, yellowW - greenW, barH);
    c.fillRect(center + greenW, barY, yellowW - greenW, barH);

    // Center line
    c.strokeStyle = isDark ? '#94a3b8' : '#475569';
    c.lineWidth = 2;
    c.beginPath();
    c.moveTo(center, barY - 2);
    c.lineTo(center, barY + barH + 2);
    c.stroke();

    // Labels
    c.font = '8px sans-serif';
    c.fillStyle = isDark ? '#94a3b8' : '#475569';
    c.textAlign = 'center';
    c.fillText(L.flat || 'Flat', barX + 10, barY + barH + 12);
    c.fillText(L.sharp || 'Sharp', barX + barW - 10, barY + barH + 12);
    c.fillText('0', center, barY + barH + 12);

    // Needle
    var clampedCents = Math.min(50, Math.max(-50, cents || 0));
    var needleX = center + (clampedCents / 50) * (barW / 2);
    var cAbs = Math.abs(clampedCents);
    var needleColor = cAbs <= 10 ? '#22c55e' : cAbs <= 25 ? '#eab308' : '#ef4444';

    c.beginPath();
    c.moveTo(needleX, barY - 4);
    c.lineTo(needleX - 4, barY - 10);
    c.lineTo(needleX + 4, barY - 10);
    c.closePath();
    c.fillStyle = needleColor;
    c.fill();

    // Cents value
    c.font = 'bold 10px sans-serif';
    c.fillStyle = needleColor;
    c.textAlign = 'center';
    c.fillText((clampedCents > 0 ? '+' : '') + Math.round(clampedCents) + '\u00A2', needleX, barY - 13);
  }

  /**
   * Draw vibrato trace — ±50 cents deviation from mean pitch.
   */
  function drawVibratoTrace(canvas, history, isDark, labels) {
    var L = labels || {};
    if (!canvas) return;
    var c = canvas.getContext('2d');
    var W = canvas.width;
    var H = canvas.height;
    c.clearRect(0, 0, W, H);

    c.fillStyle = isDark ? '#0f172a' : '#f1f5f9';
    c.fillRect(0, 0, W, H);

    if (!history || history.length < 10) {
      c.fillStyle = isDark ? '#94a3b8' : '#475569';
      c.textAlign = 'center';
      c.font = '12px sans-serif';
      c.fillText(L.empty || 'Sustain a note to see vibrato waveform', W / 2, H / 2);
      return;
    }

    // Calculate mean MIDI for the window
    var midiVals = history.map(function(h) { return h.midi; });
    var mean = midiVals.reduce(function(a, b) { return a + b; }, 0) / midiVals.length;

    // Center line at 0
    var centerY = H / 2;
    var scaleY = H / 100; // ±50 cents maps to full height

    // Grid lines
    c.strokeStyle = isDark ? '#334155' : '#e2e8f0';
    c.lineWidth = 0.5;
    c.setLineDash([3, 3]);
    var gridCents = [-40, -20, 0, 20, 40];
    c.font = '8px sans-serif';
    c.textAlign = 'right';
    c.fillStyle = isDark ? '#94a3b8' : '#475569';
    for (var gi = 0; gi < gridCents.length; gi++) {
      var gy = centerY - gridCents[gi] * scaleY;
      c.beginPath();
      c.moveTo(30, gy);
      c.lineTo(W, gy);
      c.stroke();
      c.fillText(gridCents[gi] + '\u00A2', 28, gy + 3);
    }
    c.setLineDash([]);

    // Center line (bolder)
    c.strokeStyle = isDark ? '#475569' : '#94a3b8';
    c.lineWidth = 1;
    c.beginPath();
    c.moveTo(30, centerY);
    c.lineTo(W, centerY);
    c.stroke();

    // Draw deviation waveform
    c.beginPath();
    c.strokeStyle = '#8b5cf6';
    c.lineWidth = 2;
    c.shadowColor = '#8b5cf6';
    c.shadowBlur = 4;
    for (var i = 0; i < history.length; i++) {
      var deviation = (history[i].midi - mean) * 100; // in cents
      var px = 30 + (i / (history.length - 1)) * (W - 30);
      var py = centerY - deviation * scaleY;
      py = Math.max(4, Math.min(H - 4, py));
      if (i === 0) c.moveTo(px, py);
      else c.lineTo(px, py);
    }
    c.stroke();
    c.shadowBlur = 0;
  }

  /**
   * Draw piano keyboard visualization with highlighted range.
   */
  function drawPianoKeyboard(canvas, lowMidi, highMidi, highlightLow, highlightHigh, isDark, clickCallback) {
    if (!canvas) return;
    var c = canvas.getContext('2d');
    var W = canvas.width;
    var H = canvas.height;
    c.clearRect(0, 0, W, H);

    c.fillStyle = isDark ? '#1e293b' : '#f8fafc';
    c.fillRect(0, 0, W, H);

    var totalWhiteKeys = 0;
    var whiteKeyMidis = [];
    for (var m = lowMidi; m <= highMidi; m++) {
      var n = midiToNoteName(m);
      if (n.note.indexOf('#') === -1) {
        totalWhiteKeys++;
        whiteKeyMidis.push(m);
      }
    }

    if (totalWhiteKeys === 0) return;

    var keyW = Math.min(28, (W - 4) / totalWhiteKeys);
    var keyH = H - 20;
    var startX = (W - totalWhiteKeys * keyW) / 2;
    var blackKeyW = keyW * 0.6;
    var blackKeyH = keyH * 0.6;

    // Store key rects for click handling
    var keyRects = [];

    // White keys
    var whiteIdx = 0;
    for (var m = lowMidi; m <= highMidi; m++) {
      var n = midiToNoteName(m);
      if (n.note.indexOf('#') !== -1) continue;

      var x = startX + whiteIdx * keyW;
      var isHighlighted = highlightLow && highlightHigh && m >= highlightLow && m <= highlightHigh;

      // Key background
      c.fillStyle = isHighlighted
        ? (isDark ? '#166534' : '#bbf7d0')
        : '#ffffff';
      c.fillRect(x + 1, 0, keyW - 2, keyH);

      // Key border
      c.strokeStyle = isDark ? '#475569' : '#94a3b8';
      c.lineWidth = 1;
      c.strokeRect(x + 1, 0, keyW - 2, keyH);

      // Label on C notes
      if (n.note === 'C') {
        c.font = '7px sans-serif';
        c.fillStyle = (isHighlighted && isDark) ? '#dcfce7' : '#334155';
        c.textAlign = 'center';
        c.fillText(n.str, x + keyW / 2, keyH - 4);
      }

      keyRects.push({ midi: m, x: x + 1, y: 0, w: keyW - 2, h: keyH, black: false });
      whiteIdx++;
    }

    // Black keys (overlay)
    whiteIdx = 0;
    for (var m = lowMidi; m <= highMidi; m++) {
      var n = midiToNoteName(m);
      if (n.note.indexOf('#') !== -1) continue;

      var x = startX + whiteIdx * keyW;

      // Check if there's a sharp above this note
      if (m + 1 <= highMidi) {
        var nextN = midiToNoteName(m + 1);
        if (nextN.note.indexOf('#') !== -1) {
          var bx = x + keyW - blackKeyW / 2;
          var isHighlighted = highlightLow && highlightHigh && (m + 1) >= highlightLow && (m + 1) <= highlightHigh;

          c.fillStyle = isHighlighted
            ? (isDark ? '#15803d' : '#4ade80')
            : (isDark ? '#0f172a' : '#1e293b');
          c.fillRect(bx, 0, blackKeyW, blackKeyH);
          c.strokeStyle = isDark ? '#334155' : '#94a3b8';
          c.lineWidth = 0.5;
          c.strokeRect(bx, 0, blackKeyW, blackKeyH);

          keyRects.push({ midi: m + 1, x: bx, y: 0, w: blackKeyW, h: blackKeyH, black: true });
        }
      }
      whiteIdx++;
    }

    // Store key rects on canvas for click handling
    canvas._keyRects = keyRects;
  }

  /**
   * Draw interval staff — shows reference note and target note on a staff.
   */
  function drawIntervalStaff(canvas, refMidi, targetMidi, studentMidi, isDark, labels) {
    var L = labels || {};
    if (!canvas) return;
    var c = canvas.getContext('2d');
    var W = canvas.width;
    var H = canvas.height;
    c.clearRect(0, 0, W, H);

    c.fillStyle = isDark ? '#0f172a' : '#f8fafc';
    c.fillRect(0, 0, W, H);

    var lineGap = 12;
    var staffTop = 30;
    var staffWidth = W - 80;

    // Draw staff
    drawStaff(canvas, { x: 30, y: staffTop, width: staffWidth, lineGap: lineGap, isDark: isDark });

    // Draw reference note
    if (refMidi > 0) {
      var refNote = midiToNoteName(refMidi);
      drawNoteOnStaff(c, W * 0.35, refNote.note, refNote.octave, staffTop, lineGap, isDark ? '#3b82f6' : '#2563eb');
      c.font = '10px sans-serif';
      c.fillStyle = isDark ? '#60a5fa' : '#2563eb';
      c.textAlign = 'center';
      c.fillText(L.reference || 'Reference', W * 0.35, H - 4);
      c.fillText(refNote.str, W * 0.35, staffTop - 8);
    }

    // Draw target note
    if (targetMidi > 0) {
      var targetNote = midiToNoteName(targetMidi);
      drawNoteOnStaff(c, W * 0.6, targetNote.note, targetNote.octave, staffTop, lineGap, isDark ? '#22c55e' : '#16a34a');
      c.font = '10px sans-serif';
      c.fillStyle = isDark ? '#22c55e' : '#15803d';
      c.textAlign = 'center';
      c.fillText(L.target || 'Target', W * 0.6, H - 4);
      c.fillText(targetNote.str, W * 0.6, staffTop - 8);
    }

    // Draw student pitch (if singing)
    if (studentMidi && studentMidi > 0) {
      var stuNote = midiToNoteName(Math.round(studentMidi));
      var stuDiff = targetMidi ? Math.abs(studentMidi - targetMidi) * 100 : 999;
      var stuColor = stuDiff <= 10 ? '#22c55e' : stuDiff <= 25 ? '#eab308' : '#ef4444';
      drawNoteOnStaff(c, W * 0.8, stuNote.note, stuNote.octave, staffTop, lineGap, stuColor);
      c.font = '10px sans-serif';
      c.fillStyle = stuColor;
      c.textAlign = 'center';
      c.fillText(L.you || 'You', W * 0.8, H - 4);
      c.fillText(stuNote.str, W * 0.8, staffTop - 8);
    }
  }

