          const f0 = this.last;
          const inTuneNow = !!(f0?.voiced && f0.targetCents !== null && Math.abs(f0.targetCents) <= 25 && now - (this.points[this.points.length - 1]?.t ?? 0) < 0.3);
          this.hitNotes = this.hitNotes ?? []; // { midi, t }: wall-clock start of each note sung in tune
